     "t": "code",
     "lang": "python",
     "code": "\"\"\"\nA Lock (mutex) is the most basic synchronization primitive. It has two\nstates: locked and unlocked. Only one thread can hold the lock at a time.\n\nthreading.Lock() methods:\n  - acquire(blocking=True, timeout=-1) — acquire the lock. If blocking,\n    wait until available. Returns True if acquired, False on timeout.\n  - release() — release the lock. Raises RuntimeError if not locked.\n  - locked() — return True if the lock is currently held.\n\nUsage pattern:\n  lock = threading.Lock()\n  with lock:        # acquire on enter, release on exit\n      critical_section()\n\nThe 'with' statement is preferred because it guarantees release even if an\nexception occurs in the critical section.\n\nImportant: Lock is NOT reentrant. If a thread tries to acquire a lock it\nalready holds, it will deadlock. Use RLock for reentrant locking.\n\nLocks serialize access, so overuse can reduce concurrency. Keep critical\nsections as short as possible.\n\"\"\"\nimport threading\n\nclass BankAccount:\n    def __init__(self, balance=0):\n        self.balance = balance\n        self.lock = threading.Lock()\n\n    def deposit(self, amount):\n        with self.lock:\n            current = self.balance\n            self.balance = current + amount\n\n    def withdraw(self, amount):\n        with self.lock:\n            if self.balance >= amount:\n                self.balance -= amount\n                return True\n            return False\n\n    def transfer(self, other, amount):\n        \"\"\"Transfer with ordered locking to prevent deadlock.\"\"\"\n        first, second = sorted([self, other], key=id)\n        with first.lock:\n            with second.lock:\n                if self.balance >= amount:\n                    self.balance -= amount\n                    other.balance += amount\n                    return True\n                return False\n\nprint(\"Q279: Locks\")\naccount = BankAccount(1000)\nthreads = []\nfor _ in range(100):\n    t1 = threading.Thread(target=account.deposit, args=(10,))\n    t2 = threading.Thread(target=account.withdraw, args=(10,))\n    threads.extend([t1, t2])\n\nfor t in threads:\n    t.start()\nfor t in threads:\n    t.join()\n\nprint(f\"  After 100 deposits and 100 withdrawals of $10:\")\nprint(f\"  Balance: ${account.balance} (should be $1000)\")\n\n# Transfer demo\na1 = BankAccount(500)\na2 = BankAccount(300)\na1.transfer(a2, 200)\nprint(f\"  After transfer $200: a1=${a1.balance}, a2=${a2.balance}\")\nprint()",
