     "t": "code",
     "lang": "python",
     "code": "\"\"\"\nA Semaphore is a synchronization primitive that maintains an internal counter.\nacquire() decrements the counter (blocking if it would go below zero), and\nrelease() increments it. Unlike a Lock (which is binary), a Semaphore allows\nup to N threads to access a resource concurrently.\n\nthreading.Semaphore(value=1):\n  - acquire(blocking=True, timeout=None) — decrement counter; block if 0.\n  - release() — increment counter; wake a blocked thread.\n\nthreading.BoundedSemaphore(value=1):\n  - Same as Semaphore, but raises ValueError if release() would push the\n    counter above the initial value. This catches programming errors.\n\nUse cases:\n  - Connection pooling (limit concurrent connections).\n  - Rate limiting (limit concurrent API calls).\n  - Resource pools (limit access to finite resources).\n  - Producer-consumer with bounded buffers.\n\"\"\"\nimport threading\nimport time\n\nclass ConnectionPool:\n    \"\"\"Simulated connection pool using a semaphore.\"\"\"\n    def __init__(self, max_connections):\n        self.semaphore = threading.Semaphore(max_connections)\n        self.max = max_connections\n\n    def get_connection(self, name):\n        print(f\"    {name}: waiting for connection...\")\n        self.semaphore.acquire()\n        print(f\"    {name}: acquired connection\")\n        return name\n\n    def release_connection(self, name):\n        self.semaphore.release()\n        print(f\"    {name}: released connection\")\n\ndef use_pool(pool, name, duration):\n    pool.get_connection(name)\n    time.sleep(duration)\n    pool.release_connection(name)\n\nprint(\"Q281: Semaphores\")\npool = ConnectionPool(max_connections=2)\nthreads = [\n    threading.Thread(target=use_pool, args=(pool, f\"Client-{i}\", 0.02))\n    for i in range(4)\n]\nfor t in threads:\n    t.start()\nfor t in threads:\n    t.join()\nprint(\"  Semaphore(2) allowed max 2 concurrent connections\")\nprint()",
