     "t": "code",
     "lang": "python",
     "code": "\"\"\"\nthreading.Condition is a synchronization primitive that allows threads to\nwait for some condition to become true. It combines a lock with the ability\nto wait and notify.\n\nMethods:\n  - acquire()/release() — acquire/release the underlying lock.\n  - wait(timeout=None) — release lock, wait for notification, re-acquire.\n  - wait_for(predicate, timeout=None) — wait until predicate returns True.\n  - notify(n=1) — wake up n waiting threads.\n  - notify_all() — wake up ALL waiting threads.\n\nImportant: wait() releases the underlying lock, allows other threads to\nacquire it and modify shared state, then re-acquires the lock before\nreturning. Always use conditions inside a 'with' block.\n\nCondition is essential for producer-consumer patterns where:\n  - Producer adds data and notifies consumer.\n  - Consumer waits for data to be available.\n\nThe wait_for(predicate) pattern prevents spurious wakeups.\n\"\"\"\nimport threading\nimport time\n\nclass BoundedBuffer:\n    \"\"\"Thread-safe bounded buffer using Condition.\"\"\"\n    def __init__(self, capacity):\n        self.buffer = []\n        self.capacity = capacity\n        self.condition = threading.Condition()\n\n    def put(self, item):\n        with self.condition:\n            self.condition.wait_for(lambda: len(self.buffer) < self.capacity)\n            self.buffer.append(item)\n            self.condition.notify_all()\n\n    def get(self):\n        with self.condition:\n            self.condition.wait_for(lambda: len(self.buffer) > 0)\n            item = self.buffer.pop(0)\n            self.condition.notify_all()\n            return item\n\nprint(\"Q283: Conditions\")\nbuf = BoundedBuffer(capacity=3)\nproduced = []\nconsumed = []\n\ndef producer(n):\n    for i in range(n):\n        buf.put(i)\n        produced.append(i)\n\ndef consumer(n):\n    for _ in range(n):\n        item = buf.get()\n        consumed.append(item)\n\nt1 = threading.Thread(target=producer, args=(5,))\nt2 = threading.Thread(target=consumer, args=(5,))\nt1.start()\nt2.start()\nt1.join()\nt2.join()\n\nprint(f\"  Produced: {produced}\")\nprint(f\"  Consumed: {consumed}\")\nprint(f\"  Buffer capacity=3, all items transferred correctly: {sorted(produced) == sorted(consumed)}\")\nprint()",
